// ── subtree-facts propagation helpers ───────────────────────────────

/// `propagateSubtreeFacts(child)` — facts visible to the parent.
pub fn propagate_subtree_facts(nodes: &[Node], child: NodeId) -> SubtreeFacts {
    let n = &nodes[child];
    n.data.propagate_subtree_facts(n, nodes)
}

/// `propagateSubtreeFacts(child)` on an optional child.
pub fn propagate_subtree_facts_opt(nodes: &[Node], child: Option<NodeId>) -> SubtreeFacts {
    match child {
        Some(c) => propagate_subtree_facts(nodes, c),
        None => SubtreeFacts::NONE,
    }
}

/// `propagateNodeListSubtreeFacts(children, propagateSubtreeFacts)`.
pub fn propagate_node_list_subtree_facts(nodes: &[Node], children: &Option<NodeList>) -> SubtreeFacts {
    let Some(list) = children else {
        return SubtreeFacts::NONE;
    };
    let mut facts = SubtreeFacts::NONE;
    for &c in list.nodes.iter() {
        facts |= propagate_subtree_facts(nodes, c);
    }
    facts
}

/// `propagateNodeListSubtreeFacts` over a `Box<[NodeId]>`.
pub fn propagate_slice_subtree_facts(nodes: &[Node], children: &[NodeId]) -> SubtreeFacts {
    let mut facts = SubtreeFacts::NONE;
    for &c in children {
        facts |= propagate_subtree_facts(nodes, c);
    }
    facts
}

/// `propagateModifierListSubtreeFacts(modifiers)`.
pub fn propagate_modifier_list_subtree_facts(nodes: &[Node], modifiers: &Option<ModifierList>) -> SubtreeFacts {
    let Some(list) = modifiers else {
        return SubtreeFacts::NONE;
    };
    let mut facts = SubtreeFacts::NONE;
    for &c in list.nodes.iter() {
        facts |= propagate_subtree_facts(nodes, c);
    }
    facts
}

/// `propagateEraseableSyntaxListSubtreeFacts(children)` — type arguments
/// always contribute TypeScript.
pub fn propagate_eraseable_syntax_list_subtree_facts(children: &Option<NodeList>) -> SubtreeFacts {
    if children.is_some() {
        SubtreeFacts::CONTAINS_TYPE_SCRIPT
    } else {
        SubtreeFacts::NONE
    }
}
